import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { PartnerService } from '../../services/partner.service';

@Component({
  selector: 'app-partner-login',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './partner-login.html',
  styleUrls: ['./partner-login.css'],
})
export class PartnerLoginComponent {
  credentials = { email: '', password: '' };
  errorMessage = '';
  isLoading = false;

  constructor(private partnerService: PartnerService, private router: Router) {}

  onSubmit() {
    this.isLoading = true;
    this.errorMessage = '';
    this.partnerService.login(this.credentials).subscribe({
      next: (response) => {
        this.isLoading = false;
        localStorage.setItem('token', response.token);
        this.router.navigate(['/partner-dashboard']);
      },
      error: (error) => {
        this.isLoading = false;
        this.errorMessage = error?.error?.error || 'Login failed. Please try again.';
      },
    });
  }
}
<div class="auth-container">
  <div class="auth-card partner-card">
    <div class="auth-header">
      <a routerLink="/home" class="back-link">&larr; Back to Home</a>
      <div class="partner-badge">Doctor / Partner Portal</div>
      <h2>Partner Login</h2>
      <p>Access your patient session dashboard</p>
    </div>

    <div *ngIf="errorMessage" class="error-alert">{{ errorMessage }}</div>

    <form (ngSubmit)="onSubmit()" #loginForm="ngForm">
      <div class="form-group">
        <label for="email">Email Address</label>
        <input type="email" id="email" name="email" [(ngModel)]="credentials.email" required placeholder="Enter your email">
      </div>

      <div class="form-group">
        <label for="password">Password</label>
        <input type="password" id="password" name="password" [(ngModel)]="credentials.password" required placeholder="Enter your password">
      </div>

      <button type="submit" [disabled]="!loginForm.form.valid || isLoading" class="submit-btn">
        {{ isLoading ? 'Logging in...' : 'Log In' }}
      </button>

      <p class="auth-footer">
        Not registered yet? <a routerLink="/partner-register">Create a partner account</a>
      </p>
    </form>
  </div>
</div>
